import { defineConfig } from 'astro/config';
import mdx from '@astrojs/mdx';
import sitemap from '@astrojs/sitemap';
import tailwind from '@astrojs/tailwind';
import { readFileSync, existsSync } from 'fs';

// Load per-page lastmod dates generated by prebuild.mjs
// Falls back to empty object if file doesn't exist (e.g. first run)
let sitemapDates = {};
if (existsSync('./sitemap-dates.json')) {
  try {
    sitemapDates = JSON.parse(readFileSync('./sitemap-dates.json', 'utf-8'));
  } catch {
    console.warn('⚠️  Could not read sitemap-dates.json — lastmod will be omitted');
  }
}

// https://astro.build/config
export default defineConfig({
  site: 'https://www.bestanswerhub.com',
  output: 'static',
  
  integrations: [
    tailwind({
      applyBaseStyles: false,
    }),
    mdx(),
    sitemap({
      filter: (page) => !page.includes('/go/'),
      changefreq: 'weekly',
      priority: 0.7,
      // Accurate per-page lastmod — sourced from each page's hardcoded `today` date.
      // Generated at build time by prebuild.mjs. Only pages with a known date get lastmod.
      serialize(item) {
        const date = sitemapDates[item.url] ?? sitemapDates[item.url.replace(/\/$/, '')];
        if (date) item.lastmod = date;
        return item;
      },
      i18n: {
        defaultLocale: 'en',
        locales: {
          en: 'en-US',
        },
      },
    }),
  ],
  
  markdown: {
    shikiConfig: {
      theme: 'github-dark',
      wrap: true,
    },
    gfm: true,
  },
  
  build: {
    format: 'directory',
  },
  
  vite: {
    build: {
      cssMinify: true,
    },
  },
});
